// @vitest-environment jsdom
/**
 * Smoke test: routes render without React errors, and the player wiring works against a fake
 * `window.YT` (installed before rendering, so the real API script never loads). The catalog is a
 * fixture here because catalog.json is regenerated by the extract script.
 */
import { act } from 'react';
import { createRoot } from 'react-dom/client';
import { MemoryRouter } from 'react-router-dom';
import { afterEach, beforeAll, beforeEach, describe, expect, it, vi } from 'vitest';
import App from './App';
import type { YTPlayerOptions } from './lib/youtube';
import { getPlayerState, resetPlayer } from './store/player';
import type { Catalog } from './types';

const fixture: Catalog = {
  version: 1,
  generatedAt: '2026-11-26',
  categories: [
    {
      id: 'new-hindi',
      title: 'New Hindi Hits',
      playlistId: 'PL1',
      songs: [
        {
          videoId: 'i96UO8-GFvw',
          title: 'Aaoge Tum Kabhi (Official)',
          name: 'Aaoge Tum Kabhi',
          artist: 'The Local Train',
          duration: 265,
          source: 'heatmap',
          heatmap: [1, 0.9, 0.1, 0.2, 0.6, 0.3, 0.2, 0.5, 0.2, 0.1],
          segments: [
            { rank: 1, start: 38, end: 68, score: 0.93 },
            { rank: 2, start: 150, end: 178, score: 0.8 },
          ],
        },
        {
          videoId: 'abcdefghijk',
          title: 'Second',
          name: 'Second Song',
          artist: '',
          duration: 200,
          source: 'heatmap',
          heatmap: [],
          segments: [{ rank: 1, start: 20, end: 50, score: 1 }],
        },
      ],
    },
    {
      id: 'english-pop',
      title: 'English Pop',
      playlistId: 'PL2',
      songs: [
        {
          videoId: 'mRD0-GxqHVo',
          title: 'Heat Waves',
          name: 'Heat Waves',
          artist: 'Glass Animals',
          duration: 235,
          source: 'fallback',
          heatmap: [],
          segments: [{ rank: 1, start: 70, end: 100, score: 0 }],
        },
      ],
    },
    { id: 'retro-classics', title: 'Retro Classics', playlistId: 'PL3', songs: [] },
  ],
};

vi.mock('./lib/catalog', () => ({ loadCatalog: () => Promise.resolve(fixture) }));

interface Call {
  method: string;
  args: unknown[];
}

class FakePlayer {
  static instances: FakePlayer[] = [];
  calls: Call[] = [];
  time = 0;
  constructor(
    public el: HTMLElement,
    public options: YTPlayerOptions,
  ) {
    FakePlayer.instances.push(this);
    setTimeout(() => options.events?.onReady?.({ target: this, data: null }), 0);
  }
  private record(method: string, ...args: unknown[]) {
    this.calls.push({ method, args });
  }
  loadVideoById(o: { videoId: string; startSeconds?: number }) {
    this.record('loadVideoById', o);
    this.time = o.startSeconds ?? 0;
    setTimeout(() => this.options.events?.onStateChange?.({ target: this, data: 1 }), 0);
  }
  seekTo(s: number, allow: boolean) {
    this.record('seekTo', s, allow);
    this.time = s;
  }
  playVideo() {
    this.record('playVideo');
  }
  pauseVideo() {
    this.record('pauseVideo');
  }
  getCurrentTime() {
    return this.time;
  }
  getPlayerState() {
    return 1;
  }
  destroy() {
    this.record('destroy');
  }
}

function livePlayer(): FakePlayer {
  const live = FakePlayer.instances.filter((p) => !p.calls.some((c) => c.method === 'destroy'));
  expect(live).toHaveLength(1);
  return live[0];
}

beforeAll(() => {
  (globalThis as unknown as { IS_REACT_ACT_ENVIRONMENT: boolean }).IS_REACT_ACT_ENVIRONMENT = true;
});

beforeEach(() => {
  localStorage.clear();
  FakePlayer.instances = [];
  window.YT = { Player: FakePlayer as unknown as NonNullable<typeof window.YT>['Player'] };
  resetPlayer();
});

afterEach(() => {
  act(() => resetPlayer());
  document.body.innerHTML = '';
});

async function wait(ms = 20) {
  await act(async () => {
    await new Promise((r) => setTimeout(r, ms));
  });
}

async function renderAt(path: string, until: (el: HTMLElement) => boolean) {
  const errors: unknown[] = [];
  const spy = vi.spyOn(console, 'error').mockImplementation((...args) => errors.push(args));
  const el = document.createElement('div');
  document.body.appendChild(el);
  const root = createRoot(el);
  await act(async () => {
    root.render(
      <MemoryRouter initialEntries={[path]}>
        <App />
      </MemoryRouter>,
    );
  });
  for (let i = 0; i < 100 && !until(el); i++) await wait();
  return {
    el,
    errors,
    done: async () => {
      await act(async () => root.unmount());
      spy.mockRestore();
    },
  };
}

const playerReady = () => getPlayerState().player === 'ready';
const text = (el: HTMLElement) => el.textContent ?? '';

describe('routes render', () => {
  it('home shows every category as a section, with an empty one handled', async () => {
    const { el, errors, done } = await renderAt('/', (e) => text(e).includes('Heat Waves') && playerReady());
    expect(el.querySelectorAll('section.section')).toHaveLength(3);
    expect(text(el)).toContain('Aaoge Tum Kabhi');
    expect(text(el)).toContain('No replay data — guessed clip');
    expect(text(el)).toContain('No songs in this category yet.');
    expect(el.querySelector('[aria-label="Replay graph for Aaoge Tum Kabhi"]')).not.toBeNull();
    expect(el.querySelector('nav[aria-label="Categories"]')!.textContent).toContain('New Hindi Hits');
    expect(el.querySelector('.video-host')!.childElementCount).toBe(1);
    expect(errors).toEqual([]);
    await done();
  });

  it('a category page shows only that category', async () => {
    const { el, errors, done } = await renderAt('/c/new-hindi', (e) => text(e).includes('Second Song'));
    expect(el.querySelector('h1')!.textContent).toBe('New Hindi Hits');
    expect(text(el)).not.toContain('Heat Waves');
    expect(el.querySelector('a.tab.active')!.textContent).toContain('New Hindi Hits');
    expect(errors).toEqual([]);
    await done();
  });

  it('an unknown category is a friendly not-found page', async () => {
    const { el, errors, done } = await renderAt('/c/nope', (e) => text(e).includes('Category not found'));
    expect(text(el)).toContain('“nope”');
    expect(el.querySelector('.notfound a[href="/"]')).not.toBeNull();
    expect(errors).toEqual([]);
    await done();
  });
});

describe('playing', () => {
  it('play loads the rank-1 clip; "Full song" mid-clip keeps playing to the end without a restart', async () => {
    const { el, errors, done } = await renderAt('/c/new-hindi', (e) => text(e).includes('Aaoge Tum Kabhi') && playerReady());
    const player = livePlayer();
    expect(player.options.playerVars).toMatchObject({ playsinline: 1, rel: 0, origin: window.location.origin });
    expect(player.calls.filter((c) => c.method === 'loadVideoById')).toEqual([]);

    await act(async () => el.querySelector<HTMLButtonElement>('button[aria-label="Play Aaoge Tum Kabhi"]')!.click());
    await wait();
    expect(player.calls.find((c) => c.method === 'loadVideoById')!.args[0]).toEqual({ videoId: 'i96UO8-GFvw', startSeconds: 38 });
    expect(getPlayerState().clip).toEqual({ start: 38, end: 68 });
    expect(getPlayerState().status).toBe('playing');
    expect(el.querySelector('[data-testid="clip-range"]')!.textContent).toBe('0:38–1:08');

    player.time = 50;
    await wait(300);
    const before = player.calls.length;
    const toggle = el.querySelector<HTMLInputElement>('input[aria-label="Full song: Aaoge Tum Kabhi"]')!;
    await act(async () => toggle.click());
    await wait();
    expect(JSON.parse(localStorage.getItem('music:prefs:v1')!).fullSong).toEqual(['i96UO8-GFvw']);
    expect(getPlayerState().clip).toEqual({ start: 0, end: 265 });
    expect(player.calls.slice(before).filter((c) => c.method === 'seekTo' || c.method === 'loadVideoById')).toEqual([]);
    expect(el.querySelector('[data-testid="clip-range"]')!.textContent).toBe('0:00–4:25');

    player.time = 70;
    await wait(300);
    expect(player.calls.slice(before).filter((c) => c.method === 'seekTo' || c.method === 'loadVideoById')).toEqual([]);

    await act(async () => toggle.click());
    await wait();
    expect(getPlayerState().cursor?.slot).toBe(1);
    expect(player.calls.at(-1)).toEqual({ method: 'loadVideoById', args: [{ videoId: 'abcdefghijk', startSeconds: 20 }] });
    expect(errors).toEqual([]);
    await done();
  });

  it('a clip end moves on to the next song; Space pauses; a player error skips the song', async () => {
    const { el, errors, done } = await renderAt('/', (e) => text(e).includes('Second Song') && playerReady());
    const player = livePlayer();
    await act(async () => el.querySelector<HTMLButtonElement>('button[aria-label="Play Aaoge Tum Kabhi"]')!.click());
    await wait(300);
    player.time = 68;
    await wait(300);
    expect(player.calls.filter((c) => c.method === 'loadVideoById').at(-1)!.args[0]).toEqual({ videoId: 'abcdefghijk', startSeconds: 20 });

    await act(async () => window.dispatchEvent(new KeyboardEvent('keydown', { key: ' ', code: 'Space', bubbles: true })));
    expect(player.calls.at(-1)!.method).toBe('pauseVideo');
    expect(getPlayerState().status).toBe('paused');

    await act(async () => player.options.events!.onError!({ target: player as never, data: 150 }));
    await wait();
    expect(text(el)).toContain('The owner doesn’t allow playing it here');
    expect(player.calls.filter((c) => c.method === 'loadVideoById').at(-1)!.args[0]).toEqual({ videoId: 'mRD0-GxqHVo', startSeconds: 70 });
    expect(el.querySelector<HTMLButtonElement>('button[aria-label="Play Second Song"]')!.disabled).toBe(true);
    expect(errors).toEqual([]);
    await done();
  });

  it('a segment chip plays that clip', async () => {
    const { el, errors, done } = await renderAt('/c/new-hindi', (e) => text(e).includes('Aaoge Tum Kabhi') && playerReady());
    const player = livePlayer();
    await act(async () => el.querySelector<HTMLButtonElement>('button[aria-label="Play Aaoge Tum Kabhi from 2:30 to 2:58"]')!.click());
    await wait();
    expect(player.calls.find((c) => c.method === 'loadVideoById')!.args[0]).toEqual({ videoId: 'i96UO8-GFvw', startSeconds: 150 });
    expect(getPlayerState().clip).toEqual({ start: 150, end: 178 });
    expect(errors).toEqual([]);
    await done();
  });
});
